#!/usr/bin/env python3
"""Embed the closed A05 release schemas; check mode never mutates generated bytes."""
import json
import sys
from pathlib import Path
root = Path(__file__).resolve().parents[2]
target = root / "backend/src/Modules/Catalog/Infrastructure/Schemas/release.json"
expected = json.dumps({p.name.removesuffix(".schema.json"): json.loads(p.read_text())
                       for p in sorted((root / "contracts/catalog").glob("*.schema.json"))},
                      ensure_ascii=False, indent=2) + "\n"
if "--check" in sys.argv:
    if not target.exists() or target.read_text() != expected:
        sys.exit("Catalog release schemas are stale; run make gen-catalog-schemas")
else:
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(expected)
